from .service import stream_rows

def take(resource, transform, limit):
    if limit == 0:
        return []
    stream = stream_rows(resource, transform)
    result = []
    try:
        for row in stream:
            result.append(row)
            if len(result) >= limit:
                break
    except BaseException:
        # Consuming failed. stream_rows has normally closed the resource
        # already, and close() on a finished generator is a no-op. If the
        # stream is still suspended, close it, but keep the original error.
        try:
            stream.close()
        except BaseException:
            pass
        raise
    stream.close()
    return result

