def _close_after_error(resource):
    # An iteration or transform error is active: the original error must win,
    # so a failure from cleanup is discarded here.
    try:
        resource.close()
    except BaseException:
        pass


def stream_rows(resource, transform):
    try:
        while True:
            row = resource.read_next()
            if row is None:
                break
            yield transform(row)
    except GeneratorExit:
        # Explicit generator.close(): no iteration or transform error is
        # active, so a cleanup failure propagates out of close().
        resource.close()
        raise
    except BaseException:
        # Iteration or transform error (or an exception thrown into the
        # generator): close once and re-raise the original error.
        _close_after_error(resource)
        raise
    # Exhaustion: close once; a cleanup failure propagates.
    resource.close()
